import { useCallback, useMemo, useState } from 'react';
import { Keypair, Horizon } from '@stellar/stellar-sdk';

export interface GalaxyAccountBalance {
  asset: string;
  /** Issuer account of a non-native asset. Two assets can share a code but
   *  have different issuers, so this must be kept to tell them apart. */
  issuer?: string;
  amount: string;
}

/** Minimal shape of a Horizon balance line, avoided depending on an SDK-internal type name. */
interface RawBalanceLine {
  asset_type: string;
  asset_code?: string;
  asset_issuer?: string;
  balance: string;
}

/**
 * Testnet network config, inlined here instead of imported from
 * @galaxy-kj/core-stellar-sdk. That package's published npm releases (as of
 * 5.0.2) expose only a single unsafe "main" entry point that transitively
 * requires server-only, Supabase-backed modules (it throws at import time
 * without SUPABASE_URL/SUPABASE_ANON_KEY) — there is no "exports"/"browser"
 * subpath a real standalone npm install can resolve to its browser-safe
 * source instead. Depending on it here would re-introduce exactly the
 * crash this hook exists to avoid, so this hook is built only on
 * @stellar/stellar-sdk (the underlying SDK Galaxy DevKit's own
 * browser-safe code wraps), which installs and resolves safely on its own.
 */
const TESTNET_NETWORK = {
  horizonUrl: 'https://horizon-testnet.stellar.org',
  friendbotUrl: 'https://friendbot.stellar.org',
} as const;

/**
 * Minimal wallet hook built directly on @stellar/stellar-sdk's browser-safe
 * primitives (Keypair, Horizon) instead of the server-side
 * StellarService/InvisibleWalletService, which pull in Node-only and
 * Supabase-backed code that cannot run in the browser.
 *
 * Keypair generation happens on-device; the secret key never leaves this
 * hook. This is a minimal demo wallet (testnet only) — for production use,
 * pair this with a real signing flow (hardware wallet, wallet extension, or
 * a backend-issued session) rather than holding secrets in memory.
 */
export function useGalaxyWallet() {
  const network = TESTNET_NETWORK;
  const server = useMemo(() => new Horizon.Server(network.horizonUrl), [network]);

  const [publicKey, setPublicKey] = useState<string | null>(null);
  const [balances, setBalances] = useState<GalaxyAccountBalance[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const loadAccount = useCallback(
    async (address: string) => {
      const account = await server.loadAccount(address);
      const rawBalances = account.balances as unknown as RawBalanceLine[];
      setBalances(
        rawBalances.map((b) => ({
          asset: b.asset_type === 'native' ? 'XLM' : b.asset_code ?? b.asset_type,
          issuer: b.asset_type === 'native' ? undefined : b.asset_issuer,
          amount: b.balance,
        }))
      );
    },
    [server]
  );

  /** Generates a fresh keypair on this device and funds it via Friendbot (testnet only). */
  const createWallet = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const keypair = Keypair.random();
      if (network.friendbotUrl) {
        const response = await fetch(`${network.friendbotUrl}?addr=${keypair.publicKey()}`);
        if (!response.ok) {
          throw new Error(`Friendbot funding failed: ${response.statusText}`);
        }
      }
      await loadAccount(keypair.publicKey());
      setPublicKey(keypair.publicKey());
      return keypair.publicKey();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to create wallet');
      throw err;
    } finally {
      setLoading(false);
    }
  }, [network, loadAccount]);

  /** Connects to an existing account by its public key (G...). */
  const connect = useCallback(
    async (address: string) => {
      setLoading(true);
      setError(null);
      try {
        await loadAccount(address);
        setPublicKey(address);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to connect');
        throw err;
      } finally {
        setLoading(false);
      }
    },
    [loadAccount]
  );

  return { publicKey, balances, loading, error, createWallet, connect };
}

import { useGalaxyWallet } from '../hooks/use-galaxy-wallet';

const Home = () => {
  const { publicKey, balances, loading, error, createWallet } = useGalaxyWallet();

  const handleCreateWallet = async () => {
    try {
      await createWallet();
    } catch (err) {
      console.error('Failed to create wallet:', err);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-purple-900 via-blue-900 to-indigo-900 flex items-center justify-center">
      <div className="max-w-md mx-auto bg-white rounded-xl shadow-md overflow-hidden">
        <div className="p-8">
          <div className="uppercase tracking-wide text-sm text-indigo-500 font-semibold">{{PROJECT_NAME}}</div>
          <h1 className="block mt-1 text-lg leading-tight font-medium text-black">Welcome to Galaxy DevKit</h1>
          <p className="mt-2 text-gray-500">Build Stellar DApps with ease</p>

          <div className="mt-6 space-y-4">
            {!publicKey ? (
              <button
                onClick={handleCreateWallet}
                disabled={loading}
                className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-2 px-4 rounded disabled:opacity-50"
              >
                {loading ? 'Creating wallet...' : 'Create Testnet Wallet'}
              </button>
            ) : (
              <div className="text-green-600 font-semibold break-all">Connected: {publicKey}</div>
            )}

            {balances.length > 0 && (
              <ul className="text-sm text-gray-700 space-y-1">
                {balances.map((b) => (
                  <li key={`${b.asset}:${b.issuer ?? 'native'}`}>
                    {b.amount} {b.asset}{b.issuer ? ` (${b.issuer})` : ''}
                  </li>
                ))}
              </ul>
            )}

            {error && <div className="text-red-600 text-sm">{error}</div>}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Home;

import '../styles/globals.css';
